/**
 * `role` actions bound to a client.
 *
 * @stability stable
 */
export type RoleActions = {
  readonly role: {
    /** Reads the ENSv2 roles an account holds on a name, or at the root of a registry or resolver. */
    readonly get: Bound<typeof role.get>;
    /** Grants ENSv2 roles to an account on a name, or at the root of a registry or resolver. Resolves once the transaction is submitted. */
    readonly grant: BoundWrite<typeof role.grant>;
    /** Grants ENSv2 roles to an account on a name, or at the root of a registry or resolver. Resolves once the receipt is in. */
    readonly grantSync: Bound<typeof role.grantSync>;
    /** Revokes ENSv2 roles from an account on a name, or at the root of a registry or resolver. Resolves once the transaction is submitted. */
    readonly revoke: BoundWrite<typeof role.revoke>;
    /** Revokes ENSv2 roles from an account on a name, or at the root of a registry or resolver. Resolves once the receipt is in. */
    readonly revokeSync: Bound<typeof role.revokeSync>;
  };
};

