/**
 * `batch` bound to a client.
 *
 * @stability stable
 */
export type BatchActions = { readonly batch: batch.Bound };

/**
 * Adds `batch` to a client.
 *
 * @stability stable
 * @category decorators
 * @since 1.0.0
 */
export const batchActions =
  () =>
  (client: Client<object>): BatchActions => ({
    batch: (options) => batch(client, options),
  });

/**
 * Every action group bound to a client.
 *
 * @stability stable
 */
export type EnsActions = ApprovalActions &
  DnsActions &
  EventActions &
  MigrationActions &
  NameActions &
  PermissionActions &
  PlanActions &
  PrimaryNameActions &
  RecordActions &
  RegistrationActions &
  RegistryActions &
  ResolverActions &
  RoleActions &
  SubnameActions &
  WrapperActions &
  BatchActions;

/**
 * Adds every ENS action group to a client.
 *
 * **Example** (A client with every action)
 *
 * ```ts
 * import { Ensforge, ensActions } from "@ensforge/sdk"
 *
 * const ens = Ensforge.create({ publicClient, walletClient }).extend(ensActions())
 * ```
 *
 * @stability stable
 * @category decorators
 * @since 1.0.0
 */
export const ensActions =
  () =>
  (client: Client<object>): EnsActions => ({
    ...approvalActions()(client),
    ...dnsActions()(client),
    ...eventActions()(client),
    ...migrationActions()(client),
    ...nameActions()(client),
    ...permissionActions()(client),
    ...planActions()(client),
    ...primaryNameActions()(client),
    ...recordActions()(client),
    ...registrationActions()(client),
    ...registryActions()(client),
    ...resolverActions()(client),
    ...roleActions()(client),
    ...subnameActions()(client),
    ...wrapperActions()(client),
    ...batchActions()(client),
  });
